import React, { useState } from "react";
import { Search as SearchIcon } from "@airbus/icons/react";
import {
  Button,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogHeader,
  Divider,
  Header,
  Hidden,
  IconButton,
  SideNav,
  SideNavItem,
  SideNavSection,
  Tab,
  Tabs,
  Typography,
} from "../components";
import { StoryObj } from "@storybook/react";

const meta = {
  title: "General/Templates/Responsive",
  id: "Templates/Responsive",
};
export default meta;
type Story = StoryObj<unknown>;

export const Responsive: Story = {
  // tags: ['!dev'], //hide this story from having a seperate link
  render: () => {
    const [showDialog, setShowDialog] = useState(false);
    const [showSideNav, setShowSideNav] = useState(false);
    const [page, setPage] = useState("/home");
    const navigateTo = (page: string) => {
      setPage(page);
      setShowSideNav(false);
    };
    return (
      <div>
        <Hidden down="sm">
          <Header appName="App">
            <Tabs value={page} onChange={(event, value) => setPage(value)}>
              <Tab value="/home">Home</Tab>
              <Tab value="/more">More</Tab>
              <Tab value="/about">About</Tab>
            </Tabs>
            <IconButton variant="ghostNegative">
              <SearchIcon />
            </IconButton>
            <Button variant="primary" onClick={() => setShowDialog(true)}>
              Contact
            </Button>
          </Header>
        </Hidden>
        <Hidden up="sm">
          <Header
            appName="App"
            showMenuButton
            onMenuButtonClick={() => setShowSideNav(true)}
          >
            <IconButton variant="ghost">
              <SearchIcon />
            </IconButton>
          </Header>
          <SideNav open={showSideNav} onClose={() => setShowSideNav(false)}>
            <SideNavSection style={{ paddingTop: 56, flex: 1 }}>
              <SideNavItem
                selected={page === "/home"}
                onSelected={() => navigateTo("/home")}
              >
                Home
              </SideNavItem>
              <SideNavItem
                selected={page === "/more"}
                onSelected={() => navigateTo("/more")}
              >
                More
              </SideNavItem>
              <SideNavItem
                selected={page === "/about"}
                onSelected={() => navigateTo("/about")}
              >
                About
              </SideNavItem>
            </SideNavSection>
            <Divider inset />
            <Button
              variant="primary"
              onClick={() => setShowDialog(true)}
              style={{ margin: "0.5rem 1rem" }}
            >
              Contact
            </Button>
          </SideNav>
        </Hidden>
        <Container component="main">
          <Typography variant="h1">{page}</Typography>
          <Dialog open={showDialog} onClose={() => setShowDialog(false)}>
            <DialogHeader>Contact</DialogHeader>
            <DialogContent>Please contact us</DialogContent>
            <DialogActions>
              <Button variant="primary" onClick={() => setShowDialog(false)}>
                Close
              </Button>
            </DialogActions>
          </Dialog>
        </Container>
      </div>
    );
  },
};
